(()=>{
const canvas=document.querySelector('#battlefield'),ctx=canvas.getContext('2d'),mini=document.querySelector('#minimap'),mctx=mini.getContext('2d'),W=1200,H=720;
const races=[{id:'crown',name:'The Crown',title:'Kingdom of Aster',symbol:'♜',color:'#d7bd75',accent:'#7790a3',desc:'Stalwart knights and disciplined footmen.'},{id:'clans',name:'Ashen Clans',title:'The Ashen Clans',symbol:'⚒',color:'#cc775d',accent:'#a34d3e',desc:'Hard-hitting raiders who fear no battle.'},{id:'grove',name:'Verdant Court',title:'The Verdant Court',symbol:'❋',color:'#a9bd76',accent:'#5f8c64',desc:'Swift wardens bound to the living wilds.'}];
const data={crown:{worker:'Squire',soldier:'Footman',heavy:'Knight',building:'Keep',costWorker:80,costSoldier:110,costHeavy:180},clans:{worker:'Gruntling',soldier:'Raider',heavy:'Brute',building:'War Hall',costWorker:70,costSoldier:100,costHeavy:170},grove:{worker:'Wisp',soldier:'Thornguard',heavy:'Stag Rider',building:'Elderheart',costWorker:90,costSoldier:105,costHeavy:165}};
let race=races[0],started=false,selected=[],placing=null,last=0,gameTime=0,toastTimer,drag=null,soundOn=true,gameOver=false;
let res={gold:260,wood:180,food:4,supply:10};const units=[],buildings=[],effects=[],nodes=[];let pointer={x:0,y:0};
let seed=49;function rnd(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}const trees=[];
for(let i=0;i<190;i++){let x=18+rnd()*1164,y=20+rnd()*680;if((x<440&&y>195&&y<525)||(x>780&&y>190&&y<520)||(x>475&&x<745&&y>290&&y<435))continue;trees.push({x,y,r:11+rnd()*15,v:rnd()})}
function unit(x,y,kind,team='ally'){let stats={worker:[38,4,36],soldier:[75,13,31],heavy:[130,20,40],enemy:[85,12,29]}[kind]||[70,10,30];let u={x,y,kind,team,hp:stats[0],max:stats[0],dmg:stats[1],speed:stats[2],target:null,attackTarget:null,cool:rnd(),gather:null};units.push(u);return u}
function building(x,y,type,team='ally'){let b={x,y,type,team,hp:type==='town'?600:250,max:type==='town'?600:250,queue:0};buildings.push(b);return b}
function setup(){units.length=0;buildings.length=0;effects.length=0;nodes.length=0;res={gold:260,wood:180,food:4,supply:10};unit(185,350,'worker');unit(210,378,'worker');unit(190,320,'worker');unit(245,350,'soldier');building(160,355,'town');building(1010,350,'enemyTown','enemy');unit(945,306,'enemy','enemy');unit(950,394,'enemy','enemy');unit(870,360,'enemy','enemy');nodes.push({x:340,y:272,type:'gold',amount:1200,r:34},{x:350,y:447,type:'wood',amount:800,r:28},{x:893,y:265,type:'gold',amount:950,r:32},{x:835,y:472,type:'wood',amount:1000,r:30});selected=[];gameOver=false;log('14:32','Your forces have reached <strong>Thornvale</strong>.');log('14:33','The Ashen host holds the old road to the east.')}
function log(time,msg){let el=document.createElement('div');el.className='event';el.innerHTML=`<span class="event-time">${time}</span><span class="event-message">${msg}</span>`;document.querySelector('#event-list').prepend(el);while(document.querySelectorAll('.event').length>5)document.querySelector('.event-log .event:last-child').remove()}
function toast(msg){let t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),1900)}
function timeLabel(){let n=Math.floor(gameTime);return '14:'+String(32+n).padStart(2,'0')}
function start(r){race=r;document.querySelector('#faction-name').textContent=r.name;document.querySelector('#faction-crest').textContent=r.symbol;document.querySelector('#faction-crest').style.color=r.color;document.querySelector('#start-overlay').classList.add('hidden');started=true;setup();resize();requestAnimationFrame(frame);setTimeout(()=>document.querySelector('#battle-tip').style.opacity='.35',8500)}
const racesEl=document.querySelector('#race-options');races.forEach((r,i)=>{let b=document.createElement('button');b.className='race-option'+(!i?' active':'');b.style.setProperty('--race',r.color);b.innerHTML=`<span class="race-symbol">${r.symbol}</span><span class="race-title">${r.title}</span><span class="race-desc">${r.desc}</span>`;b.onclick=()=>{race=r;document.querySelectorAll('.race-option').forEach(x=>x.classList.remove('active'));b.classList.add('active')};racesEl.appendChild(b)});
document.querySelector('#begin-button').onclick=()=>start(race);document.querySelector('#change-faction').onclick=()=>{if(started)document.querySelector('#start-overlay').classList.remove('hidden')};
document.querySelector('#sound-toggle').onclick=e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♫':'♪';e.currentTarget.title=soundOn?'Sound on':'Sound off'};
function resize(){let r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=r.width*d;canvas.height=r.height*d;ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0)}window.addEventListener('resize',resize);
function world(e){let r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width*W,y:(e.clientY-r.top)/r.height*H}}
canvas.addEventListener('pointerdown',e=>{let p=world(e);pointer=p;drag={x:p.x,y:p.y};canvas.setPointerCapture(e.pointerId)});
canvas.addEventListener('pointermove',e=>pointer=world(e));
canvas.addEventListener('pointerup',e=>{if(!drag)return;let p=world(e),dx=p.x-drag.x,dy=p.y-drag.y;if(Math.hypot(dx,dy)>12){selected=units.filter(u=>u.team==='ally'&&u.x>=Math.min(drag.x,p.x)&&u.x<=Math.max(drag.x,p.x)&&u.y>=Math.min(drag.y,p.y)&&u.y<=Math.max(drag.y,p.y));updatePanel();drag=null;return}drag=null;clickWorld(p)});
canvas.addEventListener('contextmenu',e=>{e.preventDefault();let p=world(e);if(placing){placing=null;renderCommands();return}if(!selected.length)return;let enemy=units.find(u=>u.team==='enemy'&&dist(u,p)<35)||buildings.find(b=>b.team==='enemy'&&dist(b,p)<55);selected.forEach((u,i)=>{u.target={x:p.x+(i%3)*15,y:p.y+Math.floor(i/3)*14};u.attackTarget=enemy||null;u.gather=null});if(enemy)toast('Attack order issued');else toast('Move order issued')});
function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
function clickWorld(p){if(placing){if(placing==='farm'){if(res.wood<100){toast('Need 100 lumber');return}res.wood-=100;building(p.x,p.y,'farm');log(timeLabel(),'A <strong>Supply House</strong> is under construction.')}else{if(res.wood<130){toast('Need 130 lumber');return}res.wood-=130;building(p.x,p.y,'tower');log(timeLabel(),'A <strong>Watchtower</strong> is under construction.')}placing=null;renderCommands();return}
let u=[...units].reverse().find(x=>dist(x,p)<24);if(u){selected=u.team==='ally'?[u]:[];updatePanel();return}let b=[...buildings].reverse().find(x=>dist(x,p)<50);if(b){selected=b.team==='ally'?[b]:[];updatePanel();return}
let node=nodes.find(n=>dist(n,p)<n.r+8);if(node&&selected.length){selected.filter(x=>x.kind==='worker').forEach(x=>{x.gather=node;x.target={x:node.x,y:node.y+node.r+14};x.attackTarget=null});toast('Gather order issued');return}if(selected.length){selected.forEach(x=>x.target={x:p.x,y:p.y});}}

